from pathlib import Path
from html import escape
import json
import hashlib
ROOT=Path(__file__).resolve().parent
NAV=[('index.html','Vision'),('system.html','The system'),('possibilities.html','Real life'),('economy.html','Shared value'),('governance.html','Power & rights'),('roadmap.html','The build'),('research.html','Research')]
LOGO='<svg viewBox="0 0 40 42" aria-hidden="true"><path d="M7 7L20 22L33 7M20 22V36" fill="none" stroke="currentColor" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/></svg>'
def link(href,text,cls='text-link'):return f'<a class="{cls}" href="{href}">{text}</a>'
def btn(href,text,light=False):return link(href,text+' <span aria-hidden="true">↗</span>','btn'+(' light' if light else ''))
def card(n,title,text,href=None):return f'<article class="card"><span class="num">{n}</span><h3>{title}</h3><p>{text}</p>'+ (link(href,'Explore this idea →') if href else '')+'</article>'
def heading(kicker,title,text=''):return f'<div class="section-heading"><div><span class="eyebrow">{kicker}</span><h2>{title}</h2></div><p>{text}</p></div>'
def section(content,id='',green=False):return f'<section class="section {"green" if green else ""}"{f" id={chr(34)}{id}{chr(34)}" if id else ""}><div class="wrap">{content}</div></section>'
def hero(n,title,lede):return f'<div class="wrap page-hero"><div class="chapter-art" aria-hidden="true"><span>{n[:2] if n[:2].isdigit() else "Y"}</span><i></i><i></i></div><div class="page-index"><a href="index.html">Evolve Y</a> / {n}</div><span class="eyebrow">The next chapter · A proposed direction</span><h1>{title}</h1><p class="lede">{lede}</p></div>'
def subnav(items):return '<div class="wrap"><nav class="subnav" aria-label="On this page">'+''.join(link('#'+a,b,'') for a,b in items)+'</nav></div>'
def table(headers,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def closing(title,text,href='roadmap.html',cta='Explore the build'):return f'<section class="closing"><div class="wrap"><div><h2>{title}</h2><p>{text}</p></div>{btn(href,cta)}</div></section>'
def page(name,title,description,body):
 asset_versions={asset:hashlib.sha256((ROOT/'assets'/asset).read_bytes()).hexdigest()[:12] for asset in ('style.css','design.css','app.js')}
 nav=''.join(f'<a href="{path}"'+(' aria-current="page"' if path==name else '')+f'>{label}</a>' for path,label in NAV)
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} — Evolve Y</title><meta name="description" content="{escape(description)}"><meta name="theme-color" content="#10120f"><meta property="og:title" content="{escape(title)} — Evolve Y"><meta property="og:description" content="{escape(description)}"><meta property="og:type" content="website"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script defer src="assets/app.js"></script></head><body><a class="skip" href="#main">Skip to content</a><div class="topline"><div class="wrap"><span>The Rousix × Federal Reserve Black evolution</span><span>One vision. Shared possibility.</span></div></div><header><div class="wrap header-inner"><a class="brand" href="index.html" aria-label="Evolve Y home">{LOGO} EVOLVE <small>Y</small></a><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav">Menu</button><nav id="main-nav" class="nav" aria-label="Main navigation">{nav}</nav></div></header><main id="main">{body}</main><footer><div class="wrap"><div class="footer-top"><div><a class="brand" href="index.html">{LOGO} EVOLVE <small>Y</small></a><p>A future worth sharing.<br>Useful intelligence. Real opportunity.<br>Power people can hold.</p></div><div class="footer-links"><span class="mini-label" style="color:#a6b8a7">Explore the proposal</span>{''.join(link(a,b,'') for a,b in NAV[1:4])}</div><div class="footer-links"><span class="mini-label" style="color:#a6b8a7">Built in the open</span>{link('governance.html','Rights & accountability','')}{link('research.html#review','What changed & why','')}{link('research/pilot-brief.md','Download the pilot brief','')}{link('https://github.com/PrototypeVersions/Evolve_Y','Source on GitHub ↗','')}</div></div><div class="footer-bottom"><span>Concept edition · 14 October 2026 · A proposed redesign; no live financial or membership offer.</span><span>{link('research.html#scope','Scope & site privacy','')} · {link('research.html#evidence','Evidence & sources','')}</span></div></div></footer></body></html>'''
 html=html.replace('</head>','<link rel="stylesheet" href="assets/design.css"></head>')
 html=html.replace('<body>',f'<body class="page-{"home" if name=="index.html" else Path(name).stem}"><div class="reading-progress" aria-hidden="true"></div>')
 html=html.replace('<main id="main">','<main id="main">')
 html=html.replace('<footer><div class="wrap">','<footer><div class="wrap"><div class="footer-wordmark" aria-hidden="true">EVOLVE Y<span>↗</span></div>')
 for asset,version in asset_versions.items():
  html=html.replace(f'assets/{asset}"',f'assets/{asset}?v={version}"')
 (ROOT/name).write_text(html)

body=f'''<section class="cinema-hero" aria-labelledby="hero-title"><img class="hero-image" src="assets/evolve-sculpture.jpg" alt="" width="1672" height="941" fetchpriority="high"><div class="hero-shade"></div><div class="wrap cinema-inner"><div class="hero-copy"><span class="eyebrow"><span class="live-dot"></span> A new chapter for shared prosperity</span><h1 id="hero-title">A future<br>worth<br><em>sharing.</em></h1><p class="hero-description">Extraordinary intelligence.<br>More human possibility.</p><div class="actions">{btn('system.html','Enter the vision')}{link('#foundation','Discover what’s possible <span aria-hidden="true">↓</span>')}</div></div><div class="hero-aside"><span class="coordinate">01 — THE SHARED FUTURE</span><p>Many contributors.<br>One unfolding possibility.</p><span class="art-credit">AI-generated concept artwork</span></div><div class="hero-bottom"><span>ROUSIX × FEDERAL RESERVE BLACK<br><b>Reimagined as one connected vision.</b></span><a href="#foundation" aria-label="Scroll to explore">SCROLL TO EXPLORE <span aria-hidden="true">↓</span></a><span>CAPABILITY / AGENCY / PROSPERITY</span></div></div></section><div class="signal-strip"><div class="wrap"><span>Human possibility, amplified.</span><span>Useful intelligence <i>✳</i> Real opportunity <i>✳</i> Shared value</span></div></div>'''
body+=section(heading('01 / The foundation','Great technology.<br><em>Greater possibility.</em>','Evolve Y is a proposed network of useful AI services, local expertise and shared infrastructure. Its business earns money by solving real problems. Its rules give participants a meaningful claim on the benefits.')+'<div class="grid-3 feature-grid">'+card('01 / MAKE PEOPLE CAPABLE','An extra pair of capable hands.','Help a small business coordinate work, a learner find a pathway, or a community finish a project. AI handles administrative effort; people keep judgment and authority.','possibilities.html')+card('02 / CONNECT REAL OPPORTUNITY','A network you can carry with you.','Bring your skills, work history and project records across providers. Access should not depend on an expensive machine, a speculative token or surrendering your identity.','system.html')+card('03 / SHARE WHAT WORKS','Prosperity with a source.','Pay people for work. Lower the cost of useful services. Share a stated portion of earned surplus. Extend access to people who cannot buy in.','economy.html')+'</div>','foundation')
body+='''<section class="human-section"><div class="wrap"><div class="human-heading"><span class="eyebrow">02 / The reason for all of it</span><h2>More room<br>to be <em>human.</em></h2><div><p>Time to care. A place to live. The freedom to learn, create, contribute—and say no.</p><a href="governance.html" class="text-link">Explore the social contract <span aria-hidden="true">↗</span></a></div></div><figure class="human-image"><img src="assets/shared-world.jpg" loading="lazy" width="1672" height="941" alt="An imagined sunlit community courtyard with workshops, trees and people learning together."><figcaption><span>A place for life to flourish.</span><span>AI-generated vision · Not an existing project</span></figcaption></figure><div class="human-caption"><span>OUR MEASURE OF PROGRESS</span><p>What people can do<br>with their <em>lives.</em></p><div>Useful intelligence should create more capability and choice. The business earns its place by making those outcomes real—and sharing what works.</div></div></div></section>'''
body+=section(heading('03 / A horizon of possibility','Three futures.<br><em>One useful direction.</em>','No one knows how quickly AI will transform the economy. The proposal should remain valuable across very different paths. Explore the possibilities below.')+'''<div id="scenario-tabs" class="tabs" role="tablist" aria-label="AI future scenarios"><button id="scenario-uneven" role="tab" data-key="uneven" aria-selected="true" aria-controls="scenario-panel">Uneven progress</button><button id="scenario-concentrated" role="tab" data-key="concentrated" aria-selected="false" tabindex="-1" aria-controls="scenario-panel">Concentrated abundance</button><button id="scenario-abundant" role="tab" data-key="abundant" aria-selected="false" tabindex="-1" aria-controls="scenario-panel">Broad abundance</button></div><div id="scenario-panel" class="scenario-panel" role="tabpanel" aria-labelledby="scenario-uneven"><h3 id="scenario-title">Uneven progress</h3><div><span class="mini-label" id="scenario-context">AI gets better, adoption stays difficult.</span><p id="scenario-body">Small organizations need help turning capability into reliable daily work. Sell a service that saves time after review, training and integration costs.</p></div><div><span class="mini-label" id="scenario-response">Local support + measured outcomes</span><p id="scenario-action">Keep the business useful at today’s capabilities. Expand only when customers renew and quality holds.</p></div></div><p class="fine">Scenarios are design tests, not predictions. Universal high income would require durable funding, institutions and an adequate supply of real goods and services.</p>''','futures')
body+=section(heading('04 / Begin close to home','Big ambition.<br><em>Real-world beginnings.</em>','Start in Dallas–Fort Worth with a shared operations desk for small property and maintenance organizations. Coordinate requests, documents, quotes, approvals and completion—then measure the difference.')+'''<div class="grid-2"><div class="summary-card"><span class="eyebrow">First proposed application / MREO</span><h3>One project. Everyone on the same page.</h3><p>A resident reports a repair. A coordinator prepares the work. A professional delivers it. The authorized person approves costs. A portable record shows what happened and who is responsible.</p>'''+btn('possibilities.html#walkthrough','Walk through a project',True)+'''</div><div><ul class="bullet-list"><li><strong>A clear buyer</strong>Small property operators pay for less administrative work and fewer missed steps.</li><li><strong>A real test</strong>10–20 paying organizations, a 90-day pilot, and published quality and cost measures.</li><li><strong>A larger purpose</strong>Use the same coordination foundation for learning, creator rights and community projects.</li></ul></div></div>''')
body+=section(heading('05 / Go deeper','A whole new<br><em>way forward.</em>','The ambition is large. Each part has a job, a boundary and a practical route into existence.')+'<div class="chapter-list">'+''.join(f'<a class="chapter-row" href="{p}"><span class="num">0{i+1}</span><h3>{t}</h3><p>{d}</p><span aria-hidden="true">↗</span></a>' for i,(p,t,d) in enumerate([('system.html','A connected system','How Rousix, Intermetanet, UAIE, MREO and GOE fit together.'),('economy.html','An honest economy','Who pays, what it costs, and what can actually be shared.'),('governance.html','Power that can be challenged','Rights, responsibility, member voice and meaningful exit.'),('roadmap.html','A path that can scale','Small beginnings, measurable gates and a repeatable expansion model.'),('research.html','A vision willing to change','The critical review of both original sites, and the evidence behind this direction.')]))+'</div>')
body+=closing('Build something people can believe in.','Start with a useful service. Earn trust through evidence. Let the benefits grow with the work.')
page('index.html','A future worth sharing','A new shared-prosperity vision connecting Rousix and Federal Reserve Black: useful AI, real opportunity, accountable power and value people can share.',body)

body=hero('01 / The system','One connected vision.<br><em>Many independent hands.</em>','An open network of services that helps people coordinate work and retain control over the value, knowledge and relationships they build.')+subnav([('architecture','The architecture'),('layers','The original ideas, evolved'),('compute','Compute that earns its place'),('trust','What technology can prove')])
body+=section(heading('The design principle','Federate opportunity.<br>Keep responsibility clear.','A common language for projects and agreements can connect independent organizations. A single company does not need to own every workplace, payment, identity or decision.')+'''<div class="split"><div class="stack"><div class="stack-item"><strong>People & local organizations</strong><span>Purpose · judgment · relationships</span></div><div class="stack-item"><strong>MREO / GOE / creator & learning services</strong><span>Useful applications</span></div><div class="stack-item"><strong>UAIE</strong><span>AI assistance within permission</span></div><div class="stack-item"><strong>Intermetanet</strong><span>Portable records & coordination</span></div><div class="stack-item"><strong>Rousix operations + independent providers</strong><span>Compute · support · reliability</span></div></div><div><h3>The shared project record</h3><p>The common unit is a project with a purpose, participants, permissions, offers, approvals, evidence, costs and a completion history. Each person sees only what their role requires.</p><p>This record can move with its participants. Providers compete on reliability, price and support. The network becomes more valuable as more people can work together, while leaving remains practical.</p><p class="fine">Proposed architecture. The published site demonstrates the vision; it does not run these services.</p></div></div>''','architecture',True)
layers=[
('Rousix','Useful infrastructure','An accountable operator providing integration, support and quality control. Optional compute supply is purchased against actual demand.','Transparent service fees and interchangeable providers replace mandatory hardware ownership.'),
('Intermetanet','A common coordination layer','Shared formats for permissions, agreements, task status, invoices and evidence. Connect existing tools before replacing them.','Start with signed, exportable records and normal payments. Add shared ledgers only where independent parties need them.'),
('UAIE','Intelligence people can direct','AI helps search, draft, compare and coordinate. Every consequential action has an authorized person, bounded scope and an evidence trail.','Model choice, spending limits, evaluation and the ability to stop. AI does not acquire independent legal or financial authority.'),
('MREO','Property & local services','Standardized property information and professional coordination. Start with maintenance and document workflows; later test transaction support.','Human choice, documented fees and homeowner equity protection. A faster sale is not automatically an affordable home.'),
('GOE / GESGOE','An opportunity exchange','Portable skill and project profiles connect people to real work, learning and collaborators. Local verification is consent-based and fairly paid.','No universal social score, mandatory biometric census or pay-to-rank labor market.'),
('Federal Reserve Black','Shared prosperity & accountable capital','Preserve the ambition to widen productive ownership and return value to participants. Evolve this into transparent benefit rules and separate, properly structured capital activity.','Retire the suggestion of a reserve bank or governmental mandate. Service membership is distinct from investment.'),
('Learning & creators','Human capability and rights','Practical learning pathways, accessible tools and permission-based royalty records. Knowledge and culture deserve attribution and negotiated compensation.','Verify rights and outcomes. Never require a child to buy tokens or give up sensitive identity data to learn.')]
body+=section(heading('The original ideas, evolved','Every layer has a purpose.','The names preserve continuity. Their revised roles replace a universal financial system with a modular network that can grow one useful service at a time.')+''.join(f'<div class="layer"><div class="layer-name">{n}</div><div><h3>{t}</h3><p>{d}</p></div><div><span class="mini-label">What changes</span><p>{c}</p></div></div>' for n,t,d,c in layers),'layers')
body+=section(heading('Put the workload first','Compute belongs where<br>it works best.','Ownership and technical location are different questions. People can share in a well-run enterprise without every household hosting a server.')+table(['Workload','Sensible starting point','What must be demonstrated'],[
('Everyday AI assistance','Established hosted models, with a replaceable provider interface.','Quality, privacy, full task cost and acceptable response time.'),('Sensitive or offline tasks','Local models on devices the organization already owns, when fit for purpose.','Security, maintenance burden and quality against the hosted alternative.'),('Batch jobs & rendering','Screened independent or regional providers.','Verified job completion, utilization, metering, energy and depreciation costs.'),('Frontier model training','Specialized infrastructure operated by capable suppliers.','Tightly coupled compute and networking; a home-device mesh is not presumed competitive.'),('Community workspaces','Rented space and shared equipment after demand is shown.','Occupancy, accessibility, power, cooling, insurance and stand-alone unit economics.')])+'''<p class="fine">Design judgment informed by the IEA’s evidence on physical energy and infrastructure constraints. <a href="research.html#evidence">See sources.</a> Hardware sales, network traffic and token issuance are not evidence of recurring customer demand.</p>''','compute')
body+=section('<div class="split"><div><span class="eyebrow">Honest technical foundations</span><h2>Verification is useful.<br>Judgment still matters.</h2></div><div><h3>A valid record is not the same as a fair decision.</h3><p>A signature can establish who authorized a record. A cryptographic proof can establish that a specified computation ran correctly. Neither proves that the input was true, the model was unbiased, the policy was just or the outcome was lawful.</p><p>Keep personal data off public ledgers. Use minimum necessary disclosure, a correction process and human appeals. Claims about zero-knowledge systems, immutable ownership or automatic compliance need a specific threat model, implementation and independent tests.</p><h3>Build a shared standard before a new currency.</h3><p>A versioned schema and export tools create immediate utility. Additional tokens and blockchains add costs and responsibilities. Adopt them only if an independently assessed use case is better served than by simpler infrastructure.</p></div></div>','trust')
body+=closing('A system is only as good as what it helps people do.','Explore the applications that connect the vision to ordinary life.','possibilities.html','See the applications')
page('system.html','One connected vision','The proposed roles of Rousix, Intermetanet, UAIE, MREO, GOE and shared prosperity in one practical architecture.',body)

body=hero('02 / Real life','Extraordinary capability.<br><em>Ordinary, meaningful uses.</em>','The promise becomes real in a repaired home, a completed project, a fair payment, a useful skill or an hour returned to someone’s life.')+subnav([('first','Start with MREO'),('walkthrough','A project walkthrough'),('next','What comes next'),('people','Participation without a buy-in')])
body+=section(heading('The first proposed service','A shared operations desk<br>for property and repair work.','Small operators juggle messages, documents, estimates and scheduling across disconnected tools. A reliable coordination service is a problem worth paying to solve.')+'''<div class="grid-3">'''+card('THE CUSTOMER','Small property operators','Start with organizations managing recurring maintenance or property preparation. They pay a transparent monthly service fee. Contractors are paid for their work through ordinary agreements.')+card('THE SERVICE','AI with accountable people','Collect requests, organize evidence, compare quotes, draft updates and reconcile invoices. A named human checks the work and approves commitments.')+card('THE BENEFIT','Less friction, better completion','Measure administrative hours, turnaround, rework, disputes and payment delay. Publish the full cost, including review and support. A polished demo alone proves none of these.')+'''</div><div class="note" style="margin-top:25px">Proposed pilot boundaries: no autonomous lending, tenant selection, legal advice, property custody or investment activity. These require distinct expertise, authority and operating arrangements.</div>''','first')
body+=section(heading('Walk through a project','From a request<br>to work well done.','This fictional example shows the intended experience. It does not submit a request, book a contractor, use an AI model or move money.')+'''<div class="grid-2"><div><span class="tag proposed">Illustrative service journey</span><h3 style="margin-top:25px">A repair at a small apartment building.</h3><p>A resident needs a reliable repair, a contractor needs clear instructions and prompt payment, and the operator needs confidence that the work was done. Their interests overlap, but they are not identical.</p><p>The platform should coordinate those interests without hiding who decides, who pays or who can challenge the result.</p><p class="fine">Each participant can export the records they are entitled to access. Sensitive resident details are not exposed to every bidder.</p></div><div class="demo-step"><span id="demo-count" class="step-count">STEP 1 / 5</span><div aria-live="polite" aria-atomic="true"><h3 id="demo-title">A request becomes a shared record.</h3><p id="demo-body">A coordinator collects the request and the relevant evidence.</p><div id="demo-human" class="note">Human responsibility: confirm scope and permission.</div></div><div class="demo-controls"><button class="btn outline" id="demo-prev" disabled>← Previous</button><button class="btn" id="demo-next">Next step →</button></div></div></div>''','walkthrough')
body+=section(heading('An ecosystem earned over time','The same foundation.<br>New forms of opportunity.','These are expansion options, not concurrent launch commitments. Each must find a paying customer, prove a useful outcome and meet its own requirements.')+table(['Application','The useful service','Launch condition'],[
('MREO exchange & coordination','Property packages, professional services, transparent offers and closing coordination.','Verified inventory, licensed partners, clear fees, secure documents and demonstrated customer demand.'),
('GOE opportunity network','Consented skills profiles, real project matching and paid local verification.','Verified demand, transparent selection criteria, fair compensation and an accessible dispute process.'),
('Learning & community capability','Practical training, project-based mentoring and access to AI tools.','Funded seats, teacher involvement, accessible evaluation and safeguards for children. No speculative rewards.'),
('Creator rights & royalties','A clear record of permission, use, contractual splits and payments.','Consenting rights holders, license verification, payment reconciliation and a process for disputed ownership.'),
('Insurance & claims assistance','Help organize evidence, explain process steps and track a claim.','Appropriate professional partners. Preserve review and appeal; no autonomous coverage decisions.'),
('Rousix compute services','Metered processing for paying customers through qualified suppliers.','Benchmarks and signed demand that cover energy, hardware, networking, support and replacement.'),
('Economic hubs','Shared workspaces, local support, equipment and collaboration.','Pilot in rented space first. A building and a compute business must each justify their costs.'),
('Cross-border commerce','Translate, coordinate and exchange records between willing partners.','Local language support, actual counterparties and jurisdiction-specific professional review.')]),'next')
body+=section('<div class="split"><div><span class="eyebrow">Participation without a buy-in</span><h2>You should not have to<br>own capital to belong.</h2></div><div><p>Workers can earn for real work. Small businesses can buy useful services. Researchers can evaluate claims. Communities can shape local priorities. People unable to work or invest must still be included in the purpose of the system.</p><p>Start with open learning materials and sponsored access. As revenue permits, dedicate a visible budget to accessibility and community-selected services. Do not require investment, hardware ownership, biometric enrollment or a religious or political affiliation.</p><p>Sharing rewards only in proportion to spending would favor those who already have the most. A separate access budget and member voice help prevent contribution-based rewards from becoming the whole account of fairness.</p></div></div>','people',True)
body+=closing('Make the useful thing. Then make it widely available.','The economics must work for the people using it, the people delivering it and the business supporting it.','economy.html','Explore shared value')
page('possibilities.html','Real opportunity, in ordinary life','A practical MREO-first pilot, followed by learning, creator rights, local services and useful compute.',body)

body=hero('03 / Shared value','Prosperity needs<br><em>a real source.</em>','The business should make money because it helps people. The public benefit should follow an explicit rule, funded by what the business actually earns.')+subnav([('business','Who pays & why'),('model','Explore the economics'),('distribution','How value is shared'),('income','Beyond universal high income')])
body+=section(heading('A business with a customer','Sell coordination.<br>Earn the right to grow.','The initial product is a paid service for organizations. Customer acquisition, human review and support are real costs; AI does not make them disappear.')+table(['Revenue channel','What the customer receives','Proposed boundary'],[
('Organization subscription','A maintained workspace, AI assistance, project records and a defined support allowance.','Test a $250/month starting assumption; this is a model input, not a current offer. Publish usage limits.'),
('Implementation & support','Data migration, workflow setup, training and additional human assistance.','Price separately and disclose the full expected cost before a commitment.'),
('Later coordination or transaction fees','Documented administration or services that produce a specific customer benefit.','Disclose before use. No hidden pay-to-rank placement or charging for an unprovided service.'),
('Later infrastructure services','Measured useful compute or workspace capacity with verified demand.','No presumed profit from token issuance, machine sales or recruiting new participants.')])+'''<div class="grid-2" style="margin-top:30px"><div><h3>Why it could be profitable</h3><p>A repeatable workflow and reusable integrations can reduce delivery cost across many customers. Local support, trusted records and predictable execution create value beyond access to a generic AI model.</p></div><div><h3>Why it might fail</h3><p>Customers may prefer existing software. Human review can consume the margin. Sales may be expensive. AI improvements may make the service a commodity. A small paid pilot tests these possibilities before infrastructure spending.</p></div></div>''','business')
fields=[('customers','Paying organizations',100,0,100000,1,'Customers in the modeled month.'),('price','Monthly price / organization ($)',250,0,10000,1,'Illustrative subscription only.'),('variable','Direct cost / organization ($)',90,0,10000,1,'AI, support, processing and review.'),('fixed','Fixed monthly costs ($)',12000,0,10000000,100,'Team, sales, insurance, tooling and other overhead.'),('tax','Tax provision (%)',25,0,100,1,'Simplified estimate on positive operating profit.'),('reserve','Reserve / after-tax profit (%)',25,0,100,1,'Cash retained before distributions.'),('share','Share of distributable surplus (%)',30,0,100,1,'Total participant and community pool.'),('members','Eligible member count',250,1,1000000,1,'Illustrative equal division of the member pool.')]
form='<form id="economics-form"><div class="calc-fields">'+''.join(f'<label class="field" for="input-{n}">{label}<input id="input-{n}" name="{n}" type="number" value="{v}" min="{mi}" max="{ma}" step="{st}" required inputmode="decimal"><small>{desc}</small></label>' for n,label,v,mi,ma,st,desc in fields)+'</div><p id="calc-error" class="calc-error" role="alert"></p><button type="button" id="reset-model" class="btn outline">Reset assumptions ↻</button></form>'
results='''<div class="calc-results" id="calc-results"><span class="mini-label" style="color:#c4d4c6">Modeled monthly distributable surplus</span><div class="big-result" id="available">$2,250</div><div class="ledger-line"><span>Subscription revenue</span><strong id="revenue">$25,000</strong></div><div class="ledger-line"><span>Direct delivery costs</span><strong id="direct">$9,000</strong></div><div class="ledger-line"><span>Fixed costs</span><strong id="fixed-result">$12,000</strong></div><div class="ledger-line"><span>Operating profit / loss</span><strong id="operating">$4,000</strong></div><div class="ledger-line"><span>Tax provision</span><strong id="tax-result">$1,000</strong></div><div class="ledger-line"><span>Reserve retained</span><strong id="reserve-result">$750</strong></div><div class="calc-bar" aria-hidden="true"><span></span><span></span><span></span><span></span></div><p>Allocation bar: costs · tax · reserve · distributable surplus</p><div class="ledger-line"><span>Shared pool<br><small id="calc-share-label">30% of distributable surplus</small></span><strong id="shared">$675</strong></div><div class="ledger-line"><span>Operating company retains</span><strong id="company">$1,575</strong></div><div class="ledger-line"><span>Illustrative benefit / member</span><strong id="per-member">$2</strong></div><div class="ledger-line"><span>Community access budget</span><strong id="community">$236</strong></div><p>Operating break-even: <strong id="breakeven">75 paying organizations</strong>.</p><p id="model-state" aria-live="polite">This scenario supports a modest shared benefit, not a guaranteed income.</p></div>'''
body+=section(heading('Explore the economics','Change the assumptions.<br>See what remains.','Every number below is illustrative. The calculator runs in your browser. It is a unit-economics exercise, not a forecast, valuation, investment return or universal-income model.')+'<div class="calc">'+form+results+'</div>'+'''<div class="article"><h3 style="margin-top:35px">The calculation is intentionally visible.</h3><p>Revenue = paying organizations × price. Direct cost = organizations × direct cost per organization. Operating profit = revenue − direct cost − fixed cost. Positive operating profit funds the tax provision; positive after-tax profit funds the reserve. The remaining positive amount is distributable surplus.</p><p>The chosen sharing percentage creates a common pool: 65% for eligible members and 35% for community access. The remainder stays with the operating company. The equal member division is a simple illustration; final eligibility and allocation require an agreed charter. Amounts are rounded for display; no extra money is created by rounding.</p><p>This one-month model excludes a detailed balance sheet, working-capital timing, financing, depreciation and capital purchases. Enter an appropriate allowance in costs or reserves before using it for planning. It does not model churn, customer acquisition over time, tax law or the additional staff required at scale. A positive result is not proof of commercial feasibility.</p><div class="note">At 20 customers using the default price and cost assumptions, the pilot loses $8,800 per month before startup costs. That learning period needs an explicit budget. New customers’ capital must never be disguised as earned surplus.</div></div>''','model')
body+=section(heading('Four distinct benefits','Share the gains.<br>Do not count them twice.','Customer savings, wages, ownership and company distributions are different things. The proposed network must make each one visible.')+'''<div class="allocation"><div><strong>01</strong><h3>Useful savings</h3><p>Customers keep reduced costs and time. A saved hour is not automatically cash income, and does not by itself create a dividend.</p></div><div><strong>02</strong><h3>Fair payment</h3><p>Workers and providers are paid for delivered work under clear contracts. Their ordinary pay is a cost, not a discretionary community benefit.</p></div><div><strong>03</strong><h3>Shared surplus</h3><p>A published, enforceable rule allocates a portion of residual earnings after costs, taxes and reserves. Payouts can be zero.</p></div><div><strong>04</strong><h3>Wider access</h3><p>A separate community budget supports people who cannot purchase or contribute. The proposed allocation is selected with member oversight.</p></div></div><div class="note" style="margin-top:30px">Proposed ownership is a legal and governance question. A profile, token, device purchase or membership label does not establish equity, a guaranteed payout or voting rights. Any investment arrangement remains separate, with its own proper documentation and review.</div>''','distribution')
body+=section('<div class="split"><div><span class="eyebrow">The bigger economic question</span><h2>What if AI makes<br>high income universal?</h2></div><div><p>It would be a profound opportunity. But technical abundance does not decide who owns productive assets, who receives purchasing power or how much housing, energy, care and land are available. Those are economic and political questions.</p><p>A credible long-term vision combines three routes: make essential goods and services more abundant; broaden claims on productive value; and support institutions that provide income security. Public transfers, social insurance, public services, worker ownership and shorter working time can play different roles. This company cannot enact or finance that settlement by itself.</p><p>If jobs remain important, the network should make people more capable and improve work. If paid labor becomes less central, it should help people organize care, education, creativity and community life without making human worth depend on employment.</p><h3>Measure freedom as well as income.</h3><p>Track essential costs, time autonomy, access, meaningful choice and who is left out. A larger payout alongside rising housing costs or lost rights may not be progress.</p></div></div>','income',True)
body+=section(heading('A necessary correction','Purchases do not<br>pay for themselves.','The original sites sometimes propose reimbursing purchases using a premium directed into productive infrastructure. That ambition needs a different funding mechanism.')+'''<div class="grid-2"><div><h3>The funding-base problem</h3><p>In the published example, a customer pays $1,340 for $1,000 of goods and is described as receiving $1,340 after three years. If $1,000 pays the merchant, only $340 remains to fund the future payment. Without another funding source, $340 must grow to $1,340: about 58% per year before costs.</p><p class="fine">Calculation: (1,340 ÷ 340)<sup>1/3</sup> − 1 ≈ 57.96%. This tests the stated example’s funding arithmetic, not the performance of an audited operating business. <a href="https://federalreserveblack.org/press">Original source ↗</a></p></div><div><h3>A workable replacement</h3><p>Offer an immediately useful service at a disclosed price. Pay modest rebates only from verified net earnings or a separately identified, fully funded promotional budget. Never promise full purchase reimbursement based on assumed returns.</p><p>Do not call revenue surplus, confuse token valuation with liquid money, or impose the same revenue split on every industry. Financing, settlement, taxation, insurance and monetary policy have different functions.</p></div></div>''')
body+=closing('A profitable business. A visible public benefit.','Both should stand up to scrutiny. The next question is who can hold the system to its promises.','governance.html','Explore power & rights')
page('economy.html','Shared value, with honest economics','An interactive, transparent business model and a realistic path toward broader prosperity in the AI economy.',body)

body=hero('04 / Power & rights','People need more<br><em>than good intentions.</em>','A platform can distribute its hardware while keeping all meaningful power at the center. The proposed design distributes rights, oversight and choice—and assigns clear responsibility for operations.')+subnav([('charter','The social contract'),('authority','Who decides?'),('structure','Checks on power'),('ai','AI & data boundaries')])
rights=[('Equal dignity','Access and treatment must not depend on ancestry, religion, nationality, disability, wealth or political conformity. Protect people of every faith and no faith. Apply lawful, specific eligibility requirements only where the service requires them.'),('Agency & exit','People can decline optional features, revoke future permissions and leave with usable copies of records they are entitled to possess. Explain legal retention duties and shared-record limits before participation.'),('Clear economic rights','Publish fees, eligibility, allocation formulas and conflicts. No hidden ranking payments. Member-reserved rights and distribution rules belong in enforceable documents, not just website copy.'),('Privacy by default','Collect what the task needs. Separate identity verification from a person’s general profile. Offer non-biometric alternatives. No public personal-data ledger or universal behavioral score.'),('Reasons & recourse','Explain consequential decisions, identify the responsible party and provide timely human review. Preserve evidence and make corrections visible without exposing private information.'),('A right to be included','Design for disability, low bandwidth, different languages and limited resources. Budget for access. Contribution-based rewards cannot be the only route to benefit.')]
body+=section(heading('Proposed social contract','Six promises that<br>need teeth.','These principles are a recommendation for the future platform. They have not been adopted as amendments to any existing company’s charter.')+'<div class="grid-2">'+''.join(card(f'0{i+1}',t,d) for i,(t,d) in enumerate(rights))+'</div>','charter')
body+=section(heading('Who decides?','Different decisions.<br>Different authority.','Operational speed and democratic legitimacy need not be enemies. Give people a say where their rights are at stake, and give operators responsibility for delivering the service.')+'''<div id="decision-tabs" class="tabs" role="tablist" aria-label="Governance decision examples"><button id="decision-service" role="tab" data-key="service" aria-selected="true" aria-controls="decision-panel">Service failure</button><button id="decision-fee" role="tab" data-key="fee" aria-selected="false" tabindex="-1" aria-controls="decision-panel">Fee change</button><button id="decision-data" role="tab" data-key="data" aria-selected="false" tabindex="-1" aria-controls="decision-panel">Data reuse</button><button id="decision-rights" role="tab" data-key="rights" aria-selected="false" tabindex="-1" aria-controls="decision-panel">Core rights</button></div><div id="decision-panel" class="rights-display" role="tabpanel" aria-labelledby="decision-service"><span class="mini-label" id="decision-label">A service failure</span><h3 id="decision-title">The operator acts immediately.</h3><p id="decision-body">The service team restores availability, contains incidents and notifies affected people. A named incident owner publishes a review. Members can appeal the handling; an emergency is not permission to rewrite ownership rules.</p></div>''','authority')
body+=section(heading('Checks on power','Separate the roles<br>that should check one another.','A single group should not sell the service, hold the money, certify its own fairness and decide every dispute without independent challenge.')+table(['Proposed role','Responsibility','Constraint'],[
('Operating company','Product development, employment, delivery, billing and incident response.','Transparent accounts, contracts, defined service obligations and external review.'),('Member council','Represent users and contributors; approve reserved changes to fees and benefit rules.','Verified membership, fair elections, term limits and published conflicts. No token-weighted purchase of civic voice.'),('Independent rights steward','Review rights violations, conflicts and proposed changes to the charter.','Independent selection and budget, reasoned decisions, rotation and a removal process for misconduct.'),('Specialist providers','Payments, legal services, regulated financial activity and independent assurance.','Separate responsibilities, suitable qualifications and documented agreements. A partner logo is not evidence.'),('Local operators','Deliver context-sensitive services, support members and build local demand.','Common quality and rights standards; no exclusive territorial monopoly or forced vendor lock-in.')])+'''<div class="grid-2" style="margin-top:30px"><div><h3>A credible transition from founder control</h3><p>Founders need room to build. Before paid launch, propose a signed rights charter. By a defined membership milestone, elect user and worker representatives. Reserve changes to core rights for a supermajority plus independent review. Publish the actual cap table and voting map when an ownership program is considered.</p></div><div><h3>Prevent governance from becoming theater</h3><p>Fund oversight; disclose related-party transactions; publish decision records; protect complaints; and conduct a real export-and-switch exercise. Members must be able to challenge the operator without losing ordinary access. A constitution that no one can enforce is only a statement of intent.</p></div></div>''','structure')
body+=section('<div class="split"><div><span class="eyebrow">Human authority in an AI-rich world</span><h2>Capable assistance.<br>Bounded permission.</h2></div><div><ul class="bullet-list"><li><strong>Approve consequential action.</strong>AI can draft, compare and propose. Contracts, payments and other significant commitments require the appropriate person’s authorization.</li><li><strong>Keep permissions outside the model.</strong>Enforce tool access, spending limits and data boundaries in the application. A prompt alone is not an access control.</li><li><strong>Evaluate behavior, not self-description.</strong>Test accuracy, leakage, unsafe action attempts, failure recovery and disparate impacts. A fluent explanation is not evidence of faithful internal reasoning.</li><li><strong>Preserve the ability to stop.</strong>Use short-lived credentials, logs, staged deployment, rollback and incident response. Model changes do not automatically expand authority.</li><li><strong>Learn without taking people’s data.</strong>Use opted-in or suitably de-identified evaluation data with documented limitations. No silent training on private projects.</li></ul></div></div>','ai',True)
body+=section('<div class="split"><div><span class="eyebrow">Centralization vs decentralization</span><h2>Choose the structure<br>for the task.</h2></div><div><p>Centralize responsibility for security, reliability and support at the start. Distribute delivery, data rights, representation and ownership where enforceable arrangements make that meaningful. Make providers replaceable and interfaces open.</p><p>Federation adds real costs: version compatibility, assurance, disputes, identity coordination and weaker network-wide control. Introduce it only after the core workflow is stable. The aim is resilience and freedom, not decentralization as a slogan.</p><p>The platform remains a private service within society. It does not assume the authority of governments, courts, central banks, religious institutions or the people it serves.</p></div></div>')
body+=closing('Trust should survive a change of leadership.','Build the charter, technical controls and economics together. Then test them in the real world.','roadmap.html','See the build plan')
page('governance.html','Power people can hold','A proposed rights charter for AI, ownership, privacy, member voice and operational accountability.',body)

body=hero('05 / The build','A large horizon.<br><em>A small, testable beginning.</em>','Scale a service that people choose to use. Every stage should produce evidence, reveal costs and preserve the freedom to change direction.')+subnav([('roadmap','Milestones'),('scale','How it scales'),('pilot','Pilot readiness'),('stop','Reasons to stop')])
phases=[('01','Discovery','Weeks 1–3, proposed','Interview 15–25 small property operators and service providers in DFW. Observe a real workflow. Establish baseline time, cost, error and payment delay.','Gate: at least 10 qualified organizations agree to a paid, bounded pilot; identify a named buyer and a recurring problem.'),('02','Concierge pilot','90 days, proposed','Serve 10–20 organizations with one shared project workflow. Use existing AI and payment tools, human review and simple records. Offer export from day one.','Gate: repeat use and paid renewal; no material quality decline; documented time or cost improvement after all review effort.'),('03','Repeatable product','After pilot evidence','Automate the steps already understood. Standardize data, roles, permissions, event logs and onboarding. Test provider switching and recovery.','Gate: positive contribution margin including human support; acquisition payback is credible; independent security and rights review completed.'),('04','Local federation','After repeatability','Train independent operators in a second region. Give them the same interface, operating handbook, quality measures and member protections.','Gate: second-region results hold without founder-led delivery; disputes and incident response remain manageable.'),('05','Broader ecosystem','Only when justified','Add one adjacent application at a time: GOE opportunities, learning, creator royalties or contracted compute. Consider hubs only after demonstrated occupancy demand.','Gate: separate customer demand and unit economics for each service. Financing and regulated activity receive separate review.')]
body+=section(heading('Evidence before expansion','A roadmap made<br>of gates, not guarantees.','The dates below describe a possible working sequence. None of these milestones is claimed as achieved.')+'<div class="timeline">'+''.join(f'<article class="phase"><div><span class="number-stat">{n}</span><p>{time}</p></div><div><h3>{t}</h3><p>{desc}</p></div><div><span class="mini-label">Evidence to continue</span><p>{gate}</p></div></article>' for n,t,time,desc,gate in phases)+'</div>','roadmap')
body+=section(heading('Practical scaling','Replicate the method.<br>Do not multiply the complexity.','Build one reusable coordination core and a clear operating handbook. Add infrastructure only when the existing service creates demand for it.')+'''<div class="grid-3">'''+card('PRODUCT','One core, bounded modules','A versioned project schema, role-based permissions, task state, approvals and document evidence. Service-specific modules extend the core without turning every pilot into custom software.')+card('OPERATIONS','A repeatable local playbook','Standard onboarding, quality checks, escalation, support limits and training. Local teams keep relationships and context; the network maintains common quality expectations.')+card('ECONOMICS','A contribution-margin gate','Separate recurring delivery from setup work. Track human minutes and model cost per completed project. Increase price or narrow scope when review costs overwhelm value.')+'''</div><div class="article"><h3>Proposed production architecture</h3><p>Use a standard web application with segregated customer data, a relational database, encrypted object storage and queued background tasks. Store approvals and changes in an append-only event history with a documented correction mechanism. AI providers sit behind a replaceable service interface. Payments stay with established processors.</p><p>Before federation, publish a record format, export/import tests and a compatibility policy. Regional operators can eventually run conforming services with local data controls. Conformance tests, independent audits and dispute agreements matter as much as the software.</p><h3>What should be open, and what earns money?</h3><p>Open the project formats, portability tools and public governance rules. Charge for dependable hosting, integration, support and execution. Licensed domain materials and confidential customer data stay protected. A defensible business can be built on delivery, trust and expertise rather than trapping records.</p><h3>Fund the learning period explicitly.</h3><p>With the calculator’s default costs and 20 customers, three months require roughly $26,400 to cover modeled operating losses, before initial product, legal and security work. This is an illustration—not a budget quote. Scope and price the actual pilot before seeking funding. Keep any investment arrangements separate from service membership.</p></div>''','scale')
checks=['A recurring problem and a named customer willing to pay.','A baseline for time, cost, quality and payment delay.','A written scope, price, refund terms and support limits.','A responsible human for every consequential decision.','An accessible complaint and appeal process.','Working record export and a tested provider-switch route.','An explicit budget for pilot losses and startup costs.','An agreed rights charter and a proposed benefit-sharing mechanism.']
body+=section(heading('Pilot readiness','Turn a vision into<br>a reviewable decision.','Use this local checklist to discuss the first pilot. Checking a box records no application and sends nothing to a server.')+'<div class="grid-2"><div><div id="pilot-checklist" class="checklist">'+''.join(f'<label><input type="checkbox"> <span>{c}</span></label>' for c in checks)+'''</div><div class="progress-track" aria-hidden="true"><span id="pilot-progress"></span></div><p class="fine" id="pilot-state" aria-live="polite"></p></div><div class="summary-card"><span class="eyebrow">A concrete next step</span><h3>Prepare the first 90-day pilot.</h3><p>The downloadable brief includes the customer, workflow, measurement plan, scope boundaries and decisions still required.</p>'''+btn('research/pilot-brief.md','Download pilot brief',True)+'''<p class="fine">No registration or payment. A working document for planning.</p><hr class="sep"><h3>Improve the proposal.</h3><p>The source is public. Use the repository to suggest a correction, challenge an assumption or propose a bounded experiment.</p>'''+link('https://github.com/PrototypeVersions/Evolve_Y/issues','Open the project discussion on GitHub ↗')+'</div></div>','pilot')
body+=section(heading('Measure what matters','A scorecard<br>people can understand.','Publish denominators, baselines and failures alongside improvements. Participation counts alone do not demonstrate public benefit.')+table(['Dimension','What to measure','Proposed decision rule'],[
('Customer value','Net administrative time; completion time; full cost; renewal.','At least 8 of the first 10 completing organizations renew on the stated terms, with a documented meaningful improvement. Revisit the offer if not.'),('Quality & safety','Errors, rework, missed commitments, data incidents and unauthorized actions.','No severe unresolved incident; quality must not worsen against baseline. Stop affected automation while investigating.'),('Worker outcomes','Effective pay, payment delay, unpaid effort, access to opportunity and complaints.','Improved coordination must not conceal lower effective compensation or exclusion.'),('Business viability','Contribution margin after AI, payment costs, review and support; cash runway.','Positive contribution margin before scaling. Fund fixed losses transparently; no distributions from incoming investment.'),('Power & inclusion','Export success, appeal resolution, accessibility and distribution of benefits.','Complete a real exit exercise; resolve material rights gaps before adding customers.'),('Physical impact','Energy per useful task, equipment utilization and hardware life where relevant.','Buy infrastructure only when lifecycle economics and resource impact justify it.')]))
body+=section('<div class="split"><div><span class="eyebrow">Permission to change course</span><h2>A good vision can<br>survive a failed idea.</h2></div><div><p id="stop">Stop or narrow the pilot if customers will not pay, human review consumes the margin, outcomes do not improve or rights cannot be protected. Publish what failed and why. A useful local service is a better result than an unworkable global system.</p><p>Do not use token sales, promotional valuations, new member payments or hypothetical acquisitions to fill an unexplained operating deficit. If a compute service is not competitive, buy compute elsewhere. If a module is not needed, leave it out.</p><p>The long-term ambition is a network that becomes more useful as people participate—while staying answerable to them.</p></div></div>',green=True)
body+=closing('Begin where the value can be seen.','The source review and research are open to inspection. The proposal should earn confidence through its reasons.','research.html','Read the research')
page('roadmap.html','A practical path to scale','An evidence-gated pilot and scaling plan for a shared-prosperity AI and opportunity network.',body)

rou=[
('','Home','Revise','Keep accessible, useful computing and broad participation. Replace machine-led income claims with demand-led services, transparent costs and optional hardware.'),
('press-1','Press','Revise','Create a verified progress journal. Separate measured results from proposed products, financial scenarios and unrelated political commentary.'),
('founders','Founders','Revise','Use verified, consented biographies and a precise voting map. Founder control must be reconciled with member rights; a website does not amend corporate governance.'),
('get-started','Get started','Revise','Begin with a useful service and a clear price. Remove the assumption that participants should finance equipment or pay a lease-back subscription to gain opportunity.'),
('field-reports','Field reports','Revise','Keep evidence trails and bounded AI authority. Replace unsupported government, financing and acquisition assertions with reproducible results and documented agreements.'),
('finance','Finance','Revise','Separate service access, hardware purchase and financing. Clearly disclose delivery timing, total payment obligations and risk. Do not rely on speculative income to justify debt.'),
('business-plan','Business plan','Revise','Keep productive services, professional networks and wider participation. Purchases are revenue, not automatically investable surplus; full reimbursement needs a demonstrated funding source.'),
('market-cap','Market cap','Remove','Speculative token valuation is not evidence of customer demand, company value or available capital. The redesigned business does not require a multi-token economy.'),
('charter','Corporate charter','Revise','Preserve clear legal entities and responsibilities. Corporate age alone establishes neither financial credibility nor access to every funding pathway.'),
('publications-1','Publications','Revise','Create a sourced library separating independent publications, company essays, concept imagery and proposed products. Confirm original publishers and actual endorsements.'),
('commerce','Commerce','Revise','Keep interoperable transaction records. Remove universal currency pegs, fixed economy-wide revenue allocations and assumed authority over taxes or national policy.'),
('onboarding','Onboarding','Revise','Keep patient human support. Make service terms and costs clear; access should not require a wallet, token purchase or expensive hardware.'),
('buy-now','Buy now','Revise','If hardware is offered later, publish exact specifications, delivery, warranty and a workload-based value comparison. This concept site offers no checkout.'),
('affiliate','Affiliate','Remove','Defer high-value hardware referral incentives. Any later sales program should disclose commissions and reward delivered customer value rather than recruitment.'),
('community','Community','Keep','Retain education, cooperation and support. Broaden participation to people who cannot invest or buy equipment; allow disagreement and open criticism.'),
('whitepaper','White paper','Revise','Keep modular coordination and auditable records. Remove unverified valuation, automatic universal compliance and discriminatory narratives. Tokens do not confer democratic legitimacy.'),
('pitch-deck','Pitch deck','Revise','Lead with customer, workflow, price, evidence and execution. Replace token-upside comparisons and universal tax claims with a bounded commercial proposition.'),
('research','Research','Keep','Retain serious inquiry into work, income, AI and household costs. Publish methods, complete references, uncertainty, revisions and criticism.'),
('9%2F11-redemption','9/11 redemption','Remove','Remove unrelated geopolitical and authority claims from the commercial vision. Preserve civilian welfare and peaceful cooperation as universal commitments.'),
('more-press','More press','Revise','Keep useful paid work and recurring services. Test distributed compute against actual alternatives; remain open to income support for people unable to contribute labor.'),
('testimonials-1','Testimonials','Remove','Remove discriminatory and conspiratorial narratives. Future customer stories require consent, attribution and evidence of actual outcomes.'),
('sustainability','Sustainability','Revise','Keep education and critical thinking. Add actual energy, equipment-life and resource measures; learning access must not depend on speculative participation.'),
('investment','Investment','Revise','Separate investment materials from ordinary services. Claims about financial terms, eligibility and authority need their own documented review; this site solicits no investment.'),
('proprietary','Proprietary systems','Remove','Do not treat speculative physical-instantiation or broad patent-style descriptions as working infrastructure. Retain ordinary authentication only where implemented and tested.'),
('accountability','Accountability','Revise','Translate the useful concern into audit trails, complaints, due process and independent review. Separate contested litigation advocacy from claims about the product.'),
('quantitative','Quantitative','Revise','Keep attention to AI orchestration and verifiable execution. Replace deterministic legal/financial correctness claims and unsourced forecasts with reproducible task-level evaluations.'),
('roadmap','Roadmap','Revise','Retain clear onboarding. Replace machine-to-return progression with a customer pilot, evidence gates, transparent costs and a right to exit.'),
('leadership','Leadership','Remove','Replace political-personality positioning with accountable organizational roles, qualifications, succession and member representation.'),
('framework','Economic framework','Revise','Keep fair pay and responsibility for risk. A universal 80/20 allocation cannot fit every industry; the stated wage increase needs additional cost-share assumptions.'),
('decal-program','Decal program','Remove','Defer compensated advertising until there is a useful service and a funded campaign. Large promotional payouts do not validate the underlying economics.'),
('decentralization','Decentralization','Revise','Replace geopolitical restructuring and currency-authority claims with practical local control, provider choice, portable records and accountable federation.'),
('partners','Partners','Revise','A possible acquisition target is not a partner. Publish only documented relationships and their actual scope; cooperation should be voluntary.'),
('mujahideen','Mujahideen','Revise','Preserve education, pluralism and civilian dignity. Retire military or sovereign-authority framing from a private economic platform.'),
('news-briefings','News briefings','Remove','Keep unrelated geopolitical video commentary out of primary product navigation. A research archive must distinguish interpretation from verified evidence.'),
('biometric-id','Biometric identity','Revise','Use data minimization and non-biometric access. Remove identity-purchase incentives, compulsory token holdings and broad collection of sensitive identifiers.'),
('strategic-plan','Strategic deployment','Revise','Keep useful local hubs as an option. Begin with rented capacity; occupancy, power and customer demand must justify property and compute investment independently.'),
('market-intelligence','Market intelligence','Revise','Replace sweeping predictions, promotional valuations and unsupported authority claims with dated evidence, uncertainty and clear separation of analysis from operations.'),
('become-a-member','Become a member','Revise','Distinguish service access, governance membership and investment. Provide clear terms and collect only necessary data when a real service launches.'),
('music','Music','Revise','Keep creator attribution and royalty administration. Require actual permissions, licenses and evidence of use; embedded media does not establish a partnership.'),
('silk-road','Silk Road','Revise','Keep cross-border collaboration as a horizon. Expand through willing local partners and proven demand, without claiming an operational global corridor.'),
('religion','Religion','Remove','Protect freedom of belief and conscience for everyone. Optional theological essays should not function as platform rules or evidence for financial mechanisms.'),
('disclaimer','Disclaimer','Revise','Replace broad disclaimers with accurate product-level claims, full costs, risk and clear rights. Describing something as technology does not settle its financial character.'),
('lease','Lease-back','Revise','Any future compute arrangement needs metered useful work, transparent fees, payment timing and customer demand. A recurring operator charge does not create a reliable income stream.'),
('institutional-link','Institutional systems','Revise','Defer large hardware sales until specifications, demand, lifecycle costs, delivery and support are independently assessable.')]
frb=[
('','Home','Revise','Preserve broad participation, useful infrastructure and claims accountability. Remove exclusivity-as-decentralization, unsupported authority, hostile narratives and unverified endorsements.'),
('membership-subscription-1','Membership subscription','Remove','Separate a service subscription from capital placed in a fund. The new public vision contains no liquidity-facility enrollment or investment checkout.'),
('field-reports','Field reports','Revise','Keep evidence preservation and due process. Build a clear audit, correction and complaint process; separate unrelated case advocacy.'),
('finance-tool','Finance tool','Revise','A planner can organize goals, costs and funding gaps. It cannot supply capital or establish creditworthiness merely by calculating a number.'),
('strategy','Strategy','Revise','Keep productive ownership and cooperation. Replace return positioning, bank-acquisition ambition, discriminatory claims and implied public authority with a bounded service strategy.'),
('press','Press','Revise','Create a verified progress journal. The premium-funded purchase-reimbursement example has a funding-base problem; replace it with earned-surplus rebates.'),
('business-model','Business model','Revise','Reinvesting real operating cash flow is coherent. Infinite-growth or self-sustaining-liquidity claims need to give way to costs, demand, reserves and downside cases.'),
('advantage','Advantage','Revise','Keep reduced coordination friction. Replace paying extra today for assumed future reimbursement with useful services, immediate savings and disclosed fees.'),
('intermetanet','Intermetanet','Revise','Keep permissions, settlement records, contractual administration and royalties. The page correctly separates settlement from financing; narrow the universal allocation and platform-control claims.'),
('research','Research','Keep','Institutional drift is a valuable research theme. Turn it into protected rights, explicit amendment rules, independent review and meaningful exit.'),
('postdoc','Postdoctoral research','Keep','Preserve relevant scholarship with original publication links. Academic expertise does not itself validate a commercial or financial mechanism.'),
('peer-evaluations','Peer evaluations','Keep','Make criticism visible. Extend this norm to economics, technical tests and governance, with responses and revisions rather than implied commercial endorsement.'),
('positioning','Positioning','Revise','Prioritize voluntary opportunity matching and fairly paid local verification. Replace a living census or surveillance framing with user-controlled profiles and explicit consent.'),
('real-estate','Real estate','Keep','Standardized property information and professional coordination address concrete needs. Preserve homeowner choice and equity; measure housing outcomes beyond sale price.'),
('counsel','Counsel','Revise','Publish verified roles, qualifications and actual relationships. Remove implied institutional endorsement and unrelated authority claims; provide independent complaint review.'),
('justice','Justice','Revise','Translate due process into notice, reasons, human review and remedies. Keep disputed case claims separate from the service.'),
('mission','Mission','Keep','Retain cooperation across cultural differences. Anchor it in practical abilities to learn, work, create, trade and obtain fair treatment.'),
('mvp','MVP','Keep','Retain MREO-first sequencing and revenue before expansion. Start with coordination; property acquisition, lending and exchange operation are separate undertakings.'),
('terrorism','Terrorism','Remove','Remove conspiracy and religious-hostility framing. Narrow fraud controls and lawful evidence review do not confer policing or national-security authority.'),
('safe-harbor','Safe harbor','Keep','Preserve equal safety and dignity for Jewish, Palestinian and all other communities, including people without a faith. Make nondiscrimination, privacy and assistance operational.'),
('surplus','Surplus','Revise','Distinguish company profit, household income, public fiscal balance and money creation. Share actual net earnings; perpetual surplus is not a software feature.'),
('disclaimer','Disclaimer','Revise','State which capabilities exist and what participants own. Separate service terms, privacy, governance and any properly reviewed financial documents.')]
coverage=[]
for domain,items in [('rousix.org',rou),('federalreserveblack.org',frb)]:
 for path,title,status,decision in items:coverage.append(dict(site=domain,url='https://'+domain+'/'+path,title=title,status=status,decision=decision))
(ROOT/'research'/'source-review.json').write_text(json.dumps({'review_date':'2026-10-14','scope':'Public pages discovered through menus, footer and internal body links. Embedded videos, image-only assets and every linked document were not exhaustively audited. Sitemaps were unavailable.','pages':coverage},indent=2))
source_entries=[
('https://www.ilo.org/resource/news/one-four-jobs-risk-being-transformed-genai-new-ilo%E2%80%93nask-global-index-shows','ILO–NASK · Occupational exposure to generative AI · 2025','An estimated one in four jobs is potentially exposed. Exposure is not observed displacement. The study emphasizes task transformation and the importance of institutions and policy.'),
('https://arxiv.org/abs/2304.11771','Brynjolfsson, Li & Raymond · Generative AI at Work · revised 2024','A study of 5,172 customer-support agents found a 15% average increase in issues resolved per hour, with different effects across workers. This is evidence about a specific task and setting, not a universal productivity estimate.'),
('https://www.atlantafed.org/research-and-data/publications/working-papers/2026/03/24/03-firm-data-on-ai','Federal Reserve Bank of Atlanta · Firm Data on AI · 2026 working paper','A survey of almost 6,000 executives across four countries reports widespread adoption but limited self-reported realized effects so far. It reinforces the need to measure outcomes after integration and review costs.'),
('https://www.iea.org/reports/key-questions-on-energy-and-ai/executive-summary','International Energy Agency · Key Questions on Energy and AI · 2026','AI depends on physical electricity, hardware and infrastructure. Improving task efficiency can coexist with growing total demand. This informs demand-led compute procurement rather than assumptions of effortless digital abundance.'),
('https://www.ftc.gov/policy/advocacy-research/tech-at-ftc/2025/01/behind-ftcs-6b-report-large-ai-partnerships-investments','Federal Trade Commission staff · Large AI partnerships · 2025','Identifies potential concerns about access to compute, switching costs and sensitive information. These are competition concerns, not a judgment that every partnership is harmful.'),
('https://digital-strategy.ec.europa.eu/en/factpages/data-act-explained','European Commission · Data Act explained','Describes practical switching and interoperability issues. Used here as context for portable records and open interfaces, not as a claim that the same legal requirements apply to every future service.'),
('https://airc.nist.gov/airmf-resources/airmf/5-sec-core/','NIST · AI Risk Management Framework core','Govern, map, measure and manage: an organizational approach to AI risk. The design implication is assigned responsibility, continuous evaluation and controls that extend beyond the model itself.')]
body=hero('06 / Research & revision','Keep the ambition.<br><em>Earn the confidence.</em>','A critical synthesis of the two original sites. The strongest ideas deserve a business model and a governance structure that can withstand serious questions.')+subnav([('analysis','The big-picture analysis'),('changes','What changes'),('review','Full page review'),('evidence','External evidence'),('scope','Scope & privacy')])
body+=section(heading('The big-picture analysis','The valuable core is<br>coordination plus participation.','The sites ask a significant question: could the people whose work, knowledge and spending sustain an economy also have a greater stake in its infrastructure? The answer needs institutions and earned value, not just a new technical layer.')+'''<div class="article"><h3>1. The opportunity is broader capability.</h3><p>AI can make useful expertise more accessible, but organizations still need reliable workflows, context, trust and accountability. A network that combines those elements with local human service could make small organizations more capable. That is a plausible business thesis to test.</p><h3>2. Participation is not yet ownership.</h3><p>Contributing money, data, computing or work does not automatically create a right to capital returns. The proposal must specify what each participant owns, which decisions they influence and how they can enforce those rights. Distributed hardware with exclusive corporate control is a mixed architecture, not a resolution of concentrated power.</p><h3>3. Prosperity requires production and distribution.</h3><p>More output can coexist with greater inequality. A higher income can be absorbed by scarce housing or essential services. The network should therefore seek useful productivity, fair allocation and expanded real capacity together. It must avoid treating every participant as a future investor while overlooking those with little capital or limited ability to work.</p><h3>4. Finance cannot substitute for a value proposition.</h3><p>Settlement organizes payment; it does not create financing. Revenue pays suppliers and staff before it becomes profit. Valuation is not liquidity. A recurring fee is not passive income. These distinctions are the foundation of a credible successor to the reimbursement and perpetual-surplus ideas.</p><h3>5. Institutional drift is a central design problem.</h3><p>A helpful platform can become extractive as dependence grows. Open formats, limited authority, member-reserved powers, independent review and portable records help make that drift harder. They also constrain the operator’s ability to maximize lock-in, which is an intentional tradeoff.</p><h3>6. The first market matters.</h3><p>Property and maintenance coordination connects the vision to real needs and existing MREO work. It has a buyer and an observable outcome. It also carries risks: the platform must not turn repair access into surveillance or confuse higher property prices with community prosperity. The pilot should measure resident, worker and operator outcomes separately.</p><h3>7. Novelty lies in the combination—and must be demonstrated.</h3><p>AI assistants, marketplaces, cooperatives and shared infrastructure already exist in different forms. Evolve Y’s proposed difference is a portable coordination network with local delivery, transparent economics and protected benefit-sharing. It earns that difference only if the contracts, product and outcomes actually implement it.</p></div>''','analysis')
body+=section(heading('What changes','A coherent successor,<br>with explicit tradeoffs.','This is an editorial and strategic redesign. It does not change any existing corporate, ownership, investment or contractual arrangement.')+table(['Original direction','Decision','The revised direction'],[
('Distributed infrastructure and everyday participation','Keep the purpose; revise the entry point.','Useful services available on ordinary devices. Infrastructure supply follows paying demand.'),
('Consumer recapitalization / Money On Demand','Replace the mechanism.','Immediate value plus modest, conditional rebates from realized surplus. No promise of full purchase reimbursement.'),
('Multiple tokens, global currency baselines and universal tax allocation','Remove from the business model.','Normal payment rails, service-specific pricing, jurisdiction-aware records and clear financial boundaries.'),
('Centralized decentralization','Make the allocation of power explicit.','Accountable operations, local delivery, portability, member powers and independent oversight.'),
('Universal AI and opportunity exchange','Keep; narrow initial scope.','Permissioned assistants and voluntary, portable opportunity profiles. No universal social score.'),
('MREO and real-world coordination','Prioritize.','A paid local pilot with verifiable completion, professional partners and protected customer choice.'),
('Biometric identity and paid enrollment','Redesign.','Minimum necessary credentials, non-biometric alternatives and no speculative identity incentive.'),
('Economic hubs and hardware expansion','Defer until justified.','Rented capacity and demand validation before large property or compute commitments.'),
('Education, creator rights and pluralistic safe harbor','Keep and operationalize.','Accessible learning, consented licensing, fair payment, nondiscrimination and help for people who cannot buy in.'),
('Discriminatory narratives, assumed public authority, unverified partnerships and extraordinary valuations','Remove.','Universal dignity, evidence-based claims and a clear separation between a private company and public institutions.')]),'changes')
